class PaymentIn(BaseModel):
    cents: int
    currency: str

    @field_validator("cents")
    @classmethod
    def check_and_audit(cls, v):
        audit_log.insert(amount=v)        # «чтобы ни один не потерять»
        metrics.incr("payment_validated")
        if v <= 0:
            raise ValueError("non-positive amount")
        return v

@app.post("/payments", response_model=PaymentIn)
async def create_payment(p: PaymentIn):
    saved = await store(p)
    return saved
